Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The bug is caused by the GPIO interrupt status being masked before the MAC IRQ is enabled due to a hardware deficiency. This results in pending GPIO interrupts not being cleared, leading to the situation where GPIO interrupts are never reported again. The lack of a mechanism to manually clear the interrupt status before enabling the MAC IRQ exacerbates this issue.

Here is the patch:

+void txgbe_reinit_gpio_intr(struct wx *wx)
+{
+	struct txgbe *txgbe = wx->priv;
+	irq_hw_number_t hwirq;
+	unsigned long gpioirq;
+	struct gpio_chip *gc;
+	unsigned long flags;
+
+	/* for gpio interrupt pending before irq enable */
+	gpioirq = rd32(wx, WX_GPIO_INTSTATUS);
+
+	gc = txgbe->gpio;
+	for_each_set_bit(hwirq, &gpioirq, gc->ngpio) {
+		int gpio = irq_find_mapping(gc->irq.domain, hwirq);
+		struct irq_data *d = irq_get_irq_data(gpio);
+		u32 irq_type = irq_get_trigger_type(gpio);
+
+		txgbe_gpio_irq_ack(d);
+
+		if ((irq_type & IRQ_TYPE_SENSE_MASK) == IRQ_TYPE_EDGE_BOTH) {
+			raw_spin_lock_irqsave(&wx->gpio_lock, flags);
+			txgbe_toggle_trigger(gc, hwirq);
+			raw_spin_unlock_irqrestore(&wx->gpio_lock, flags);
+		}
+	}
+}
+
 static int txgbe_gpio_init(struct txgbe *txgbe)
 {
 	struct gpio_irq_chip *girq;
 	struct gpio_chip *gc;
 	struct device *dev;
 	struct wx *wx;
 	int ret;

 	wx = txgbe->wx;
 	dev = &wx->pdev->dev;

 	raw_spin_lock_init(&wx->gpio_lock);

 	gc = devm_kzalloc(dev, sizeof(*gc), GFP_KERNEL);
 	if (!gc)
 		return -ENOMEM;

 	gc->label = devm_kasprintf(dev, GFP_KERNEL, "txgbe_gpio-%x",
 				   pci_dev_id(wx->pdev));
 	if (!gc->label)
 		return -ENOMEM;

 	gc->base = -1;
 	gc->ngpio = 6;
 	gc->owner = THIS_MODULE;
 	gc->parent = dev;
 	gc->fwnode = software_node_fwnode(txgbe->nodes.group[SWNODE_GPIO]);
 	gc->get = txgbe_gpio_get;
 	gc->get_direction = txgbe_gpio_get_direction;
 	gc->direction_input = txgbe_gpio_direction_in;
 	gc->direction_output = txgbe_gpio_direction_out;

 	girq = &gc->irq;
 	gpio_irq_chip_set_chip(girq, &txgbe_gpio_irq_chip);
 	girq->default_type = IRQ_TYPE_NONE;
 	girq->handler = handle_bad_irq;

 	ret = devm_gpiochip_add_data(dev, gc, wx);
 	if (ret)
 		return ret;

 	txgbe->gpio = gc;

 	return 0;
 }



